  const win = await page.evaluate(() => {
    player.x = GOAL_X - player.w - 8;
    player.y = GROUND_Y - player.h;
    player.grounded = true;
    player.vx = 285;
    player.coins = TARGET_COINS;
    updateHUD();
    update(0.033);
    return { title: overlayTitle.textContent, text: overlayText.textContent, overlayVisible: overlay.classList.contains('visible'), pauseDisabled: pauseButton.disabled };
  });
  await page.click('#startButton');
  const gameOver = await page.evaluate(() => {
    player.lives = 1;
    player.y = H + 101;
    player.grounded = false;
    update(0.016);
    return { title: overlayTitle.textContent, text: overlayText.textContent, overlayVisible: overlay.classList.contains('visible'), pauseDisabled: pauseButton.disabled, health: healthFill.getAttribute('aria-valuenow') };
  });
  await page.click('#startButton');
  const retry = await page.evaluate(() => ({overlayVisible: overlay.classList.contains('visible'), score: scoreValue.textContent, health: healthFill.getAttribute('aria-valuenow'), pauseDisabled: pauseButton.disabled}));
  console.log(JSON.stringify({win, gameOver, retry, errors}, null, 2));
  await browser.close();
})();
